function openEquipment(requestedTab){if(roomEquipment){error('В этой комнате используется инвентарь хозяина.');return;}$('equipment').dataset.kind=kind;selectChessTab(requestedTab==='pieces'?'pieces':'boards');$('equipment').querySelector('h2').textContent=kind==='chess'?'Оформление шахмат':'Редактор нард';$('chessEquipment').hidden=kind!=='chess';$('nardsEquipment').hidden=kind==='chess';setText('equipmentLevel','Уровень героя: '+heroLevel+' · оформление не влияет на силу игры');draftEquipment={...equipment};selectNardsTab(['outside','inside','pieces','dice'].includes(requestedTab)?requestedTab:state&&kind!=='chess'?'inside':'outside');renderEquipment();$('equipment').showModal();}
function mountCollectionArrows(){for(const id of ['nardsBoards','nardsInteriors','checkers','nardsDice']){const list=$(id),frame=document.createElement('div'),controls=document.createElement('div');frame.className='collection-carousel';controls.className='collection-carousel-arrows';list.before(frame);frame.append(controls,list);const previous=document.createElement('button'),next=document.createElement('button');previous.type=next.type='button';previous.textContent='‹';next.textContent='›';previous.setAttribute('aria-label','Предыдущие варианты');next.setAttribute('aria-label','Следующие варианты');previous.setAttribute('aria-controls',id);next.setAttribute('aria-controls',id);controls.append(previous,next);const paint=()=>{previous.disabled=list.scrollLeft<=1;next.disabled=list.scrollLeft+list.clientWidth>=list.scrollWidth-2;};const scroll=direction=>list.scrollBy({left:direction*Math.max(110,list.clientWidth*.8),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});previous.onclick=()=>scroll(-1);next.onclick=()=>scroll(1);list.addEventListener('scroll',paint,{passive:true});new ResizeObserver(paint).observe(list);new MutationObserver(paint).observe(list,{childList:true});paint();}}
